# CIT 1 Gen/Update 1 (1.0.1) feature tour
# Run with `cit main.cit` or the CIT Run command in VS Code.

import { math, json, time, datetime, cli, sys, database }

# Shared values, placeholders and chained temporal limits
let mut name = "Coder"
let mut a, b, c = 2
let placeholder = _
let mut temporary <3s> after <30l> = 12
println(name, a, b, c, placeholder, temporary)
let mut account = null
println(account?.name ?? "Guest")

# Mixed collections, unique sets and immutable tuples
let mut values = list(1, "two", true)
let point = tuple(1, "north", true)
let mut unique = set(1, 2, 2, 3, 1)
let info = dict(name: "CIT", version: 1.0)
let fixedInfo = frozendict(name: "CIT", version: 1)
let frozenValues = frozenset(1, 2, 2, 3)
println(values, point, unique, info, fixedInfo, frozenValues)

# Math and statistics
println(math.ceil(3.1), math.floor(3.9), math.sqrt(16), math.cbrt(27))
println(math.mean([1, 2, 3]), math.median([1, 2, 8, 9]), math.mode([1, 2, 2, 3]))
println(math.stddev([1, 2, 3]), math.dist([0, 0], [3, 4]), math.pi, math.tau)

# JSON parsing, path queries, and formatted serialization
let data = json.parse("{\"users\":[{\"name\":\"Ada\"}]}")
println(json.query(data, "$.users[0].name"))
println(json.stringify({language: "CIT", version: 1}, indent = 2))
println(json.validate("{\"ok\":true}"), json.minify("{ \"ok\" : true }"))
println(json.colorize("{\"valid\":true}"))

# Date, time, and safe system information
let now = datetime.now()
println(datetime.format(now), datetime.timestamp(now))
println(datetime.add("2025-01-01T00:00:00Z", 2, "d"))
println(datetime.diff("2025-01-01", "2025-01-02", "h"))
println(time.strftime("%Y-%m-%d", time.localtime()))
println(sys.platform(), sys.arch(), sys.cwd(), sys.pid)

# Terminal output helpers; interactive options are available when called.
cli.table([["Month", "Sales"], ["January", 109], ["February", 112]])
cli.progress(50)
cli.spinner("Loading")
println(cli.size())

fn askForOptions() {
    let choice = cli.select(["Start", "Settings", "Exit"])
    let accepted = cli.confirm("Continue?")
    return [choice, accepted]
}

fn askForPassword() {
    return cli.password("Password:")
}

fn copyClipboardText() {
    let text = sys.clipRead()
    sys.clipWrite(text)
    return text
}

fn showSystemDetails() {
    return [sys.env("PATH"), sys.args(), sys.memory(), sys.user(), sys.cpuLoad(),
        sys.cpuInfo(), sys.networkInterfaces(), sys.which("node"), sys.isAdmin()]
}

fn showDateUtilities() {
    let measured = datetime.benchmark(() => math.sqrt(16))
    let ticks = datetime.ticker(0, 2)
    let nextRun = datetime.cron("*/5 * * * *", "2025-01-01T00:01:00Z")
    return [measured.result, measured.durationMs, ticks, nextRun]
}

# A safe SQLite example using an in-memory database and bound values.
let mut db = database.connect(":memory:")
db.run("CREATE TABLE users (id INTEGER PRIMARY KEY, name TEXT)")
db.run("INSERT INTO users (name) VALUES (?)", ["Ada"])
let users = db.all("SELECT id, name FROM users WHERE name = ?", ["Ada"])
println(users[0].name)
db.close()

# Classes, inheritance, polymorphism and custom operators
class Vector() {
    fn struct(x, y) {
        self.x = x
        self.y = y
    }

    operator +(other) {
        return Vector(self.x + other.x, self.y + other.y)
    }
}

class Animal() {
    fn struct(animalName) {
        self.name = animalName
    }

    fn make_sound() {
        println($"{self.name} makes a sound.")
    }
}

class Dog(Animal()) {
    fn struct(animalName) {
        super().struct(animalName)
    }

    fn make_sound() {
        println($"{self.name} barks: Woof!")
    }
}

let combined = Vector(2, 3) + Vector(4, 5)
println(combined.x, combined.y)
let mut dog = Dog("Rex")
dog.make_sound()

# Generic calls, variadic parameters, and async/await
fn identity<T>(value) {
    return value
}

fn addAll(*args, **kwargs) {
    return sum(args) + kwargs["extra"]
}

async fn delayedMessage() {
    await task.wait(0.01)
    return "Ready!"
}

println(identity<int>(10), identity<str>("CIT"))
println(addAll(1, 2, extra: 3))
println(delayedMessage())

# Reactive variables notify watchers only after a value changes.
reactive let mut score = 0
watch score {
    println($"Score changed to {score}")
}
score = 100

# Conditional expressions, enums and typed errors
let enum colors = (["red", "yellow", "blue", "green"])
let number = 2
println(colors.red, "Even" if (number % 2 == 0) else "Odd")

try {
    raise ValueError("Example validation error")
} except ValueError as err {
    println(err)
} finally {
    println("Validation finished")
}

# printf, exchange, loops, and text files
printf("My name is %s; I code in %s.\n", name, "CIT")
let oldValue = exchange(a, 20)
println(a, oldValue)
for (_, range(0, 2)) {
    println("This loop does not bind its range value")
}

with open("notes.txt", "write", encoding = "utf-8") as file {
    file.write("First line.\n")
    file.write("Second line.\n")
}
with open("notes.txt", "append", encoding = "utf-8") as file {
    file.write("Last line.\n")
}
